# --- Deterministic reorder policy shared by management UI and unit tests. ---
write(
    'app/src/main/java/app/ownplay/mobile/feature/settings/domain/ManualOrderPolicy.kt',
    '''package app.ownplay.mobile.feature.settings.domain\n\nobject ManualOrderPolicy {\n    fun move(ids: List<String>, id: String, direction: Int): List<String> {\n        if (direction == 0 || ids.size < 2) return ids\n        val from = ids.indexOf(id)\n        if (from < 0) return ids\n        val to = from + if (direction > 0) 1 else -1\n        if (to !in ids.indices) return ids\n        return ids.toMutableList().also { list ->\n            val value = list[from]\n            list[from] = list[to]\n            list[to] = value\n        }\n    }\n}\n''',
)
write(
    'app/src/test/java/app/ownplay/mobile/feature/settings/domain/ManualOrderPolicyTest.kt',
    '''package app.ownplay.mobile.feature.settings.domain\n\nimport org.junit.Assert.assertEquals\nimport org.junit.Test\n\nclass ManualOrderPolicyTest {\n    @Test\n    fun `move swaps one position in requested direction`() {\n        assertEquals(listOf("b", "a", "c"), ManualOrderPolicy.move(listOf("a", "b", "c"), "a", 1))\n        assertEquals(listOf("a", "c", "b"), ManualOrderPolicy.move(listOf("a", "b", "c"), "c", -1))\n    }\n\n    @Test\n    fun `move is stable at boundaries and for unknown ids`() {\n        val original = listOf("a", "b", "c")\n        assertEquals(original, ManualOrderPolicy.move(original, "a", -1))\n        assertEquals(original, ManualOrderPolicy.move(original, "c", 1))\n        assertEquals(original, ManualOrderPolicy.move(original, "missing", 1))\n    }\n}\n''',
)

