# --- Audit: backup v1 is intentionally not changed because old v1 decoders reject unknown fields. ---
audit_path = 'docs/audit/STAGE_12_STABILIZATION.txt'
audit = read(audit_path)
audit += '''\n\n## Live personalization and functional Settings refinement\n\n- Added source-stable Live category personalization (`sourceId + kind + categoryKey`) for hide/show and manual order.\n- Reused existing stable channel personalization for individual channel hide/show and manual order, preserving favorite/local name/local logo fields.\n- Category/channel personalization is applied at repository/DAO presentation queries so provider refresh does not overwrite it.\n- Added long-press vertical drag handles in Settings > Manage Live channels for categories and channels.\n- Hidden categories suppress their channels at runtime without erasing individual channel hidden/order state.\n- Settings interactive rows now have real actions; fixed build constraints are presented as read-only status rather than fake controls.\n- `Show channel logos` is wired to Live rows and loads bounded provider artwork with a text fallback.\n- `Resume playback` changes which saved-progress action is primary while retaining explicit Resume and Play from Beginning choices.\n- Settings > Manage downloads provides real pause/resume/retry/remove/open-Library actions. Help and Privacy open real internal information pages.\n- Room schema moves additively from v1 to v2 through explicit `MIGRATION_1_2`; no existing table is dropped or rewritten.\n- Existing backup format remains v1 unchanged. Its decoder rejects unknown fields, so exporting category personalization would be a breaking backup-format change and is intentionally deferred pending explicit approval. Existing backup features remain functional for their documented v1 scope.\n- This is source engineering only. No APK/AAB, signing, release, merge, auth cutover, destructive migration, or user-data deletion is authorized by this refinement.\n'''
write(audit_path, audit)

print('Stage 12 personalization/settings patch applied.')
